def ring(n, cx, cy, cz, r, rz_step=0.0, size=(0.05, 0.02, 0.09), tilt=0):
    """n ellipsoids fanned half-way round the head (mirroring makes the other half): petals, shards, quills."""
    out = []
    for i in range(n):
        a = math.pi * (0.1 + 0.8 * i / max(1, n - 1))           # 0.1π..0.9π over the right side and top
        x, z = math.cos(a) * r, math.sin(a) * r
        if x < 0.02: x = 0.02
        out.append(("ell", (cx + x, cy, cz + z), size, (tilt, math.degrees(math.pi / 2 - a), 0)))
    return out


def quills(pts, r=0.018):
    """Spikes as thin capsules: [(base, tip)]."""
    return [("cap", a, b, r) for a, b in pts]


def bristle(cx, cy, cz, r, n, length, keep, rad=0.02):
    """Spikes standing out of a sphere (quills, shards): a golden-angle spiral of n points on the right half (the mirror
    adds the left), kept where keep(direction) holds — e.g. only the back and the top."""
    out, ga = [], math.pi * (3 - math.sqrt(5))
    for i in range(n * 3):
        z = 1 - 2 * (i + 0.5) / (n * 3); rr = math.sqrt(1 - z * z); a = ga * i
        d = (abs(math.cos(a) * rr), math.sin(a) * rr, z)
        if not keep(d): continue
        base = (cx + d[0] * r, cy + d[1] * r, cz + d[2] * r); tip = (cx + d[0] * (r + length), cy + d[1] * (r + length) + length * 0.3, cz + d[2] * (r + length))
        out.append(("cap", base, tip, rad))
        if len(out) >= n: break
    return out


def spec(name, base, head, body, ears, tail, marks, face, bones=None, budgets=(2600, 2600, 900, 700)):
    P = f"SK_{name}_"
    return dict(bones=bones or {}, vols={P + "Head": head, P + "Body": body, P + "Ears": ears, P + "Tail": tail},
                marks={P + k: v for k, v in marks.items()}, face=face, base=base,
                budgets={P + "Head": budgets[0], P + "Body": budgets[1], P + "Ears": budgets[2], P + "Tail": budgets[3]}, armour=False)


