def coil(r, z, n, seg, start=0.0):
    """One turn of the coil: n rounded segments round the base (right half + the two on the axis; the mirror adds the
    rest), small enough apart that they read as a body lying in rings, not one melted blob."""
    out = []
    for k in range(n):
        a = start + math.pi * k / (n - 1)                   # 0..π: front to back round the right side
        x, y = math.sin(a) * r, -math.cos(a) * r
        out.append(("ell", (max(0.0, x) if x > 0.01 else 0.0, y, z), (seg, seg, seg * 0.75), (0, 0, math.degrees(a))))
    return out


