def _lie_low(sp, P="SK_Cobra_"):
    """The cobra lies low instead of rearing: the coil stays on the ground, the neck runs forward along it and the head
    rests just above the sand, looking ahead. Head, hood, face and head marks move down/forward together; the neck and
    its bands are rebuilt along the new line; the head and neck bones follow so the head turns about the neck."""
    d = (0.0, -0.30, -0.40)
    mv = lambda p: (p[0] + d[0], p[1] + d[1], p[2] + d[2])
    shift = lambda v: ("ell", mv(v[1]), v[2], v[3]) if v[0] == "ell" else ("cap", mv(v[1]), mv(v[2]), v[3])
    sp["vols"][P + "Head"] = [shift(v) for v in sp["vols"][P + "Head"]]
    sp["vols"][P + "Ears"] = [("ell", mv((0.07, 0.03, 0.62)), (0.07, 0.02, 0.07), (0, 0, 12))]                        # the hood folded, not spread
    neck = [("cap", (0, 0.04, 0.16), (0, -0.14, 0.21), 0.062), ("cap", (0, -0.14, 0.21), (0, -0.27, 0.24), 0.058)]
    sp["vols"][P + "Body"] = neck + [v for v in sp["vols"][P + "Body"] if not (v[0] == "cap" and v[2][2] > 0.4)]    # the rearing neck goes
    sp["face"] = [(f[0], mv(f[1]), f[2], f[3]) for f in sp["face"]]
    sp["marks"][P + "Head"] = [(c, mv(p), h) for c, p, h in sp["marks"][P + "Head"]]
    sp["marks"][P + "Ears"] = [(c, mv(p), h) for c, p, h in sp["marks"][P + "Ears"]]
    body = [m for m in sp["marks"][P + "Body"] if m[1][2] < 0.2]                                                    # coil bands + belly stay
    sp["marks"][P + "Body"] = body + [(BAND, (0, y, z), (0.08, 0.012, 0.08)) for y, z in ((-0.02, 0.18), (-0.10, 0.20), (-0.18, 0.22))]
    sp["bones"] = dict(sp.get("bones", {}), neck_01=((0, -0.20, 0.20), (0, -0.24, 0.22), "spine_01"), head=((0, -0.27, 0.22), (0, -0.30, 0.40), "neck_01"),
                       socket_head=((0, -0.30, 0.41), (0, -0.30, 0.46), "head"))


