# ================================================================ limbs that fit the animal
# Four-legged beasts play the "Q" clips: the body pitches forward and the arms become front legs. So the arms end in
# the same foot as the legs (not a round chibi hand), thick enough to carry the body, and the foot is the animal's own:
# padded paws with toes and claws, cloven hooves, elephant pads with toenails, splayed reptile claws, jointed insect legs.
CLAW, IVORY, HOOF, PAD = (0.93, 0.89, 0.80), (0.94, 0.90, 0.78), (0.20, 0.15, 0.12), (0.30, 0.22, 0.22)


def limbs(kind, claw=CLAW):
    """(volumes, marks) for the right-side front leg (the arm) and hind leg; the mirror makes the left pair."""
    T = (-0.028, 0.0, 0.028)
    if kind == "paw":
        v = [("cap", (0.13, 0, 0.39), (0.19, -0.03, 0.24), 0.05), ("ell", (0.195, -0.05, 0.215), (0.062, 0.08, 0.045), (0, 0, 0)),
             ("cap", (0.075, 0, 0.18), (0.075, 0, 0.065), 0.055), ("ell", (0.075, -0.045, 0.04), (0.066, 0.09, 0.04), (0, 0, 0))]
        v += [("ell", (0.195 + d, -0.115, 0.205), (0.022, 0.026, 0.02), (0, 0, 0)) for d in T] + [("ell", (0.075 + d, -0.125, 0.032), (0.024, 0.028, 0.02), (0, 0, 0)) for d in T]
        m = [(claw, (0.195 + d, -0.14, 0.2), (0.012, 0.012, 0.012)) for d in T] + [(claw, (0.075 + d, -0.152, 0.028), (0.013, 0.012, 0.012)) for d in T]
    elif kind == "hoof":
        v = [("cap", (0.13, 0, 0.39), (0.19, -0.03, 0.235), 0.042), ("ell", (0.19, -0.03, 0.235), (0.048, 0.048, 0.035), (0, 0, 0)), ("ell", (0.19, -0.03, 0.2), (0.052, 0.056, 0.035), (0, 0, 0)),
             ("cap", (0.075, 0, 0.18), (0.075, 0, 0.07), 0.046), ("ell", (0.075, -0.02, 0.038), (0.056, 0.06, 0.04), (0, 0, 0))]
        m = [(HOOF, (0.19, -0.03, 0.188), (0.065, 0.065, 0.028)), (HOOF, (0.075, -0.02, 0.024), (0.066, 0.07, 0.03)), (PAD, (0.19, -0.085, 0.19), (0.004, 0.01, 0.03))]
    elif kind == "pillar":
        v = [("cap", (0.13, 0, 0.39), (0.19, -0.03, 0.23), 0.068), ("ell", (0.19, -0.035, 0.205), (0.078, 0.078, 0.036), (0, 0, 0)),
             ("cap", (0.075, 0, 0.18), (0.075, 0, 0.06), 0.072), ("ell", (0.075, -0.02, 0.035), (0.082, 0.082, 0.036), (0, 0, 0))]
        m = [(IVORY, (0.19 + d, -0.105, 0.2), (0.016, 0.01, 0.014)) for d in T] + [(IVORY, (0.075 + d, -0.095, 0.03), (0.017, 0.01, 0.015)) for d in T] + [(PAD, (0.19, -0.035, 0.172), (0.08, 0.08, 0.012))]
    elif kind == "reptile":
        v = [("cap", (0.13, 0, 0.37), (0.23, -0.05, 0.24), 0.045), ("ell", (0.24, -0.07, 0.215), (0.062, 0.075, 0.03), (0, 0, 0)),
             ("cap", (0.08, 0, 0.18), (0.12, -0.02, 0.06), 0.05), ("ell", (0.125, -0.05, 0.035), (0.066, 0.09, 0.03), (0, 0, 0))]
        v += [("cap", (0.24 + d, -0.12, 0.215), (0.24 + d * 1.4, -0.165, 0.205), 0.013) for d in T] + [("cap", (0.125 + d, -0.12, 0.035), (0.125 + d * 1.4, -0.17, 0.028), 0.013) for d in T]
        m = [(claw, (0.24 + d * 1.4, -0.16, 0.205), (0.015, 0.015, 0.015)) for d in T] + [(claw, (0.125 + d * 1.4, -0.165, 0.028), (0.015, 0.015, 0.015)) for d in T]
    else:   # insect: thin jointed legs with a hooked tip
        v = [("cap", (0.12, 0, 0.36), (0.22, -0.03, 0.34), 0.022), ("cap", (0.22, -0.03, 0.34), (0.24, -0.06, 0.20), 0.019), ("cap", (0.24, -0.06, 0.20), (0.25, -0.09, 0.17), 0.013),
             ("cap", (0.07, 0, 0.20), (0.15, 0, 0.16), 0.024), ("cap", (0.15, 0, 0.16), (0.13, -0.02, 0.04), 0.02), ("cap", (0.13, -0.02, 0.04), (0.14, -0.06, 0.02), 0.013)]
        m = [(HOOF, (0.25, -0.09, 0.17), (0.02, 0.02, 0.02)), (HOOF, (0.14, -0.06, 0.02), (0.02, 0.02, 0.02)), (HOOF, (0.22, -0.03, 0.34), (0.026, 0.026, 0.026)), (HOOF, (0.15, 0, 0.16), (0.028, 0.028, 0.028))]
    return v, m


LIMB = {"hedgehog": ("paw", CLAW), "snowlynx": ("paw", CLAW), "shadowpanther": ("paw", (0.10, 0.08, 0.12)), "jackal": ("paw", (0.88, 0.68, 0.24)),
        "mossstag": ("hoof", None), "mammoth": ("pillar", None), "lavarhino": ("pillar", None), "tortoise": ("reptile", CLAW), "salamander": ("reptile", (0.98, 0.72, 0.16)),
        "scarab": ("insect", None), "scorpion": ("insect", None)}
_STD = {repr(x) for x in bb.ARMS[1:]}
for name, (kind, claw) in LIMB.items():
    sp = NEW[name]; key = next(k for k in sp["vols"] if k.endswith("_Body"))
    body = sp["vols"][key]; keep = [x for x in body if repr(x) not in _STD]
    if name == "scorpion": keep = [x for x in keep if repr(x) not in {repr(l) for l in LEGS}]; v, m = limbs(kind); v = v[3:]; m = m[1::2]   # its arms stay pincers: new legs only
    else: v, m = limbs(kind, claw or CLAW)
    sp["vols"][key] = keep + v; sp["marks"].setdefault(key, []).extend(m); sp["limb_vols"] = v

